-- PostgreSQL 13+ provides gen_random_uuid() without enabling pgcrypto.
-- This migration belongs ONLY to the Booking Service database.

CREATE TABLE IF NOT EXISTS bookings (
    booking_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Human-readable ticket/reference; generated by the Booking Service.
    booking_reference VARCHAR(30) NOT NULL UNIQUE,

    -- These IDs refer to records owned by other services.
    -- They intentionally have NO cross-service foreign keys.
    ride_id UUID NOT NULL,
    passenger_id UUID NOT NULL,
    driver_id UUID NOT NULL,

    requested_seats INTEGER NOT NULL CHECK (requested_seats > 0),

    -- APPROVING means driver accepted and Booking Service is asking Ride
    -- Service to reserve seats. Stuck APPROVING rows need reconciliation.
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING'
        CHECK (status IN (
            'PENDING',
            'APPROVING',
            'CANCELLING',
            'CONFIRMED',
            'REJECTED',
            'CANCELLED',
            'COMPLETED',
            'FAILED'
        )),

    rejection_reason TEXT,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    confirmed_at TIMESTAMPTZ,
    cancelled_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_bookings_ride_id
    ON bookings(ride_id);

CREATE INDEX IF NOT EXISTS idx_bookings_passenger_created
    ON bookings(passenger_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_bookings_driver_pending
    ON bookings(driver_id, created_at)
    WHERE status = 'PENDING';

CREATE INDEX IF NOT EXISTS idx_bookings_status
    ON bookings(status);
